import re,os,hashlib,struct,base64,glob,collections
SUF=bytes.fromhex("518D64A635DED8C1")
def nid(n):
    h=hashlib.sha1(n.encode()+SUF).digest()
    return base64.b64encode(struct.pack('>Q',struct.unpack('<Q',h[:8])[0]),b'+-').decode().rstrip('=')
print('selftest',nid('_ZnamSt11align_val_tRKSt9nothrow_t'))
impl={}
pend=[]
for root,_,fs in os.walk('core/libs'):
    for f in fs:
        if not f.endswith(('.cpp','.hpp','.h','.c')): continue
        p=os.path.join(root,f)
        try: t=open(p,encoding='utf-8',errors='ignore').read()
        except: continue
        for m in re.finditer(r'APS5_VABI\s+(\w+)_nid_postfix\s*\([^;{]*\)[^;{]*\{',t):
            body=t[m.end():t.find('\n}',m.end())]
            if 'NotImplemented' not in body: impl.setdefault(m.group(1),p)
        for m in re.finditer(r'APS5_EXPORT\("([^"]+)",\s*(\w+)\)',t):
            fn=m.group(2)
            d=re.search(r'\b'+re.escape(fn)+r'\s*\([^;{]*\)[^;{]*\{',t)
            if not d: continue
            body=t[d.end():t.find('\n}',d.end())]
            if 'NotImplemented' in body: pend.append((m.group(1),fn,p))
print('implemented names',len(impl),'pending exports',len(pend))
bynid={nid(n):n for n in impl}
diffs={}
for f in glob.glob('/tmp/prs/*.diff'):
    diffs[os.path.basename(f)[:-5]]=open(f,errors='ignore').read()
hits=[]
for N,fn,p in pend:
    if N in bynid:
        busy=[k for k,v in diffs.items() if N in v]
        hits.append((p.split('/prx/')[-1].split('/')[0],N,bynid[N],impl[bynid[N]],busy))
c=collections.Counter(h[0] for h in hits)
print('candidates by lib',c)
for h in sorted(hits): print(*h,sep=' | ')
EOF
